#define CHECK(x) do{checks++;if(!(x)){fprintf(stderr,"salvage check %d: %s\n",__LINE__,#x);exit(1);}}while(0)
typedef struct{const uint8_t*data[3];size_t bytes[3];unsigned status;uint8_t projection_sha256[32];}Fixture;
#include "salvage-fixtures.h"
typedef struct{unsigned calls,fail_at;CohStatus failure;}Digest;
typedef struct{unsigned calls,stop;}Cancel;
static Digest digest_context;static Cancel cancellation;
static CohStatus digest(void*p,CohBytes b,uint8_t out[32]){Digest*d=p;d->calls++;SHA256(b.data,b.size,out);return d->fail_at==d->calls?d->failure:COH_OK;}
static int cancelled(void*p){Cancel*c=p;c->calls++;return c->stop&&c->stop==c->calls;}
static CohSalvageDictionary out,before,projection,saved;
static CohSalvageWorkspace workspace;
static CohSalvageSources sources;
static CohCostumeImportDigest provider={digest,&digest_context,sizeof(digest_context),4096};
static CohSalvageControl control={{cancelled,&cancellation},sizeof(cancellation),256};
static CohStatus read(size_t budget,size_t retained){memset(&out,0xa5,sizeof(out));before=out;CohStatus s=coh_salvage_read(&sources,&provider,&control,&out,&workspace,budget,retained);if(s!=COH_OK)CHECK(!memcmp(&out,&before,sizeof(out)));return s;}
static void setup(const Fixture*f){memset(&sources,0,sizeof(sources));sources.provenance=1;for(unsigned i=0;i<3;i++){sources.bodies[i]=(CohBytes){f->data[i],f->bytes[i]};SHA256(f->data[i],f->bytes[i],sources.expected_sha256[i]);}digest_context=(Digest){0,0,COH_IO};cancellation=(Cancel){0,0};}
static void projection_hash(uint8_t hash[32]){projection=out;memset(projection.sha256,0,sizeof(projection.sha256));projection.provenance=0;memset(projection.schema_crc,0,sizeof(projection.schema_crc));memset(projection.dependencies,0,sizeof(projection.dependencies));projection.complete=projection.runtime_generation=projection.actor_authority=0;SHA256((const uint8_t*)&projection,sizeof(projection),hash);}
static void queries(void){uint32_t row=999,tab=999,detail=999;unsigned joins=0;for(unsigned i=0;i<out.count;i++){const CohSalvageItem*s=&out.items[i];CohSalvageText t=s->fields[0];char name[128];CHECK(t.size<sizeof(name));for(unsigned j=0;j<t.size;j++){unsigned c=(unsigned char)out.text[t.offset+j];name[j]=(char)(c>='a'&&c<='z'?c-32:c);}CohBytes key={(const uint8_t*)name,t.size};row=999;CHECK(coh_salvage_find(&out,key,&row)==COH_OK&&row==i);uint32_t reverse=999;CHECK(coh_salvage_by_id(&out,s->id,&reverse)==COH_OK&&out.items[reverse].id==s->id);row=999;CohStatus status=coh_salvage_join(&out,key,s->id,&row);CHECK(status==(reverse==i?COH_OK:COH_NOT_FOUND)&&row==(reverse==i?i:999));t=s->fields[5];CHECK(coh_salvage_tab(&out,(CohBytes){(const uint8_t*)out.text+t.offset,t.size},&tab)==COH_OK&&tab<out.tab_count);CohSalvageRange a=out.tabs[tab].members;int present=0;for(unsigned k=0;k<a.count;k++){CHECK(a.first+k<out.count);if(out.tab_members[a.first+k]==i)present=1;if(k)CHECK(out.tab_members[a.first+k]>out.tab_members[a.first+k-1]);}CHECK(present);
 for(unsigned k=0;k<s->arrays[0].count;k++){CHECK(coh_salvage_workshop(&out,i,k,&detail)==COH_OK&&detail<out.details_count);CHECK(detail+1==out.values[s->arrays[0].first+k].detail_plus_one);joins++;}detail=999;CHECK(coh_salvage_workshop(&out,i,s->arrays[0].count,&detail)==COH_NOT_FOUND&&detail==999);}
 CHECK(joins==out.workshop_joins);for(unsigned id=0;id<out.slot_count;id++){row=999;CHECK(coh_salvage_by_id(&out,id,&row)==(out.slots[id]?COH_OK:COH_NOT_FOUND)&&row==(out.slots[id]?out.slots[id]-1:999));}
 row=999;CHECK(coh_salvage_by_id(&out,UINT32_MAX,&row)==COH_NOT_FOUND&&row==999);CHECK(coh_salvage_find(&out,(CohBytes){(const uint8_t*)"unknown_missing",15},&row)==COH_NOT_FOUND&&row==999);CHECK(coh_salvage_find(&out,(CohBytes){(const uint8_t*)"\xff",1},&row)==COH_UNSUPPORTED&&row==999);CHECK(coh_salvage_find(&out,(CohBytes){(const uint8_t*)"Alpha",5},&out.count)==COH_INVALID);CHECK(coh_salvage_workshop(&out,out.count,0,&row)==COH_NOT_FOUND&&row==999);}
static void authentic_workshops(void){static const char*const names[]={"Base_Worktable_Arcane","Base_Worktable_Arcane2","Base_Worktable_Arcane3","Base_Worktable_Tech","Base_Worktable_Tech2","Base_Worktable_Tech3","Worktable_Invention"};unsigned seen=0,count=0;for(unsigned i=0;i<out.count;i++){CohSalvageRange a=out.items[i].arrays[0];for(unsigned j=0;j<a.count;j++){CohSalvageText t=out.values[a.first+j].text;unsigned k;for(k=0;k<7;k++)if(t.size==strlen(names[k])&&!memcmp(out.text+t.offset,names[k],t.size))break;CHECK(k<7);seen|=1u<<k;count++;}}CHECK(count==413&&seen==127);}
int main(void){for(unsigned f=0;f<sizeof(fixtures)/sizeof(fixtures[0]);f++){const Fixture*v=&fixtures[f];setup(v);CHECK(read(COH_SALVAGE_RAM_MAX,0)==(CohStatus)v->status);if(v->status){CHECK(!digest_context.calls);continue;}CHECK(out.complete&&out.provenance==1&&!out.runtime_generation&&!out.actor_authority&&digest_context.calls==3);CHECK(!memcmp(out.sha256,sources.expected_sha256,96));uint8_t hash[32];projection_hash(hash);CHECK(!memcmp(hash,v->projection_sha256,32));queries();}
 const Fixture*f=&fixtures[0];setup(f);CHECK(read(COH_SALVAGE_RAM_MAX,0)==COH_OK);CHECK(out.count==356&&out.id_count==412&&out.details_count==1045&&out.workshop_joins==413&&out.tab_count==6);authentic_workshops();saved=out;unsigned polls=cancellation.calls;
 /* Fixed bounded polling controls cover entry, all digest boundaries and final
  * publication without quadratic replay of every actual complete record. */
 for(unsigned i=0;i<28;i++){unsigned stop=i<4?i+1:i<24?1+(unsigned)(((uint64_t)polls*(i-3))/21):polls-(27-i);setup(f);cancellation.stop=stop;CHECK(read(COH_SALVAGE_RAM_MAX,0)==COH_CANCELLED&&cancellation.calls==stop);cancellations++;}
 setup(f);for(unsigned i=1;i<=3;i++){digest_context=(Digest){0,i,COH_IO};CHECK(read(COH_SALVAGE_RAM_MAX,0)==COH_IO&&digest_context.calls==i);}setup(f);
 for(unsigned side=0;side<3;side++){size_t n=f->bytes[side];uint8_t*copy=malloc(n+1);CHECK(copy);for(unsigned k=0;k<24;k++){setup(f);size_t length=k<12?k:((n-1)*(k-11))/12;sources.bodies[side].size=length;CHECK(read(COH_SALVAGE_RAM_MAX,0)!=COH_OK&&!digest_context.calls);cuts++;}for(unsigned k=0;k<24;k++){setup(f);memcpy(copy,f->data[side],n);size_t at=k<12?k:((n-1)*(k-11))/12;copy[at]^=255;sources.bodies[side].data=copy;CHECK(read(COH_SALVAGE_RAM_MAX,0)!=COH_OK);mutations++;}setup(f);memcpy(copy,f->data[side],n);copy[n]=0;sources.bodies[side]=(CohBytes){copy,n+1};CHECK(read(COH_SALVAGE_RAM_MAX,0)!=COH_OK);free(copy);}
 setup(f);size_t minimum=COH_SALVAGE_STACK_RESERVE+sizeof(sources)+sizeof(provider)+sizeof(control)+sizeof(out)+sizeof(workspace)+sizeof(digest_context)+sizeof(cancellation)+provider.scratch_reserve+control.scratch_reserve;for(unsigned i=0;i<3;i++)minimum+=f->bytes[i];CHECK(read(minimum,0)==COH_OK);CHECK(read(minimum-1,0)==COH_LIMIT);CHECK(read(COH_SALVAGE_RAM_MAX,SIZE_MAX)==COH_LIMIT);size_t old=6512084u+116864u;CHECK(read(minimum+old,old)==COH_OK);CHECK(read(minimum+old-1,old)==COH_LIMIT);provider.scratch_reserve=SIZE_MAX;CHECK(read(COH_SALVAGE_RAM_MAX,0)==COH_LIMIT);provider.scratch_reserve=4096;control.scratch_reserve=SIZE_MAX;CHECK(read(COH_SALVAGE_RAM_MAX,0)==COH_LIMIT);control.scratch_reserve=256;
 CHECK(coh_salvage_read(&sources,&provider,&control,&out,(CohSalvageWorkspace*)&out,COH_SALVAGE_RAM_MAX,0)==COH_INVALID);void*context=provider.context;size_t bytes=provider.context_bytes;provider.context=&out;provider.context_bytes=1;CHECK(read(COH_SALVAGE_RAM_MAX,0)==COH_INVALID);provider.context=context;provider.context_bytes=bytes;context=control.cancel.context;bytes=control.context_bytes;control.cancel.context=provider.context;control.context_bytes=provider.context_bytes;CHECK(read(COH_SALVAGE_RAM_MAX,0)==COH_INVALID);control.cancel.context=context;control.context_bytes=bytes;
 setup(f);sources.bodies[1]=sources.bodies[0];CHECK(read(COH_SALVAGE_RAM_MAX,0)==COH_INVALID);setup(f);sources.expected_sha256[2][0]^=1;CHECK(read(COH_SALVAGE_RAM_MAX,0)==COH_STATE);setup(f);memset(sources.expected_sha256[0],0,32);CHECK(read(COH_SALVAGE_RAM_MAX,0)==COH_STATE);
 setup(f);uint8_t*copies[3];for(unsigned i=0;i<3;i++){copies[i]=malloc(f->bytes[i]);CHECK(copies[i]);memcpy(copies[i],f->data[i],f->bytes[i]);sources.bodies[i].data=copies[i];}CHECK(read(COH_SALVAGE_RAM_MAX,0)==COH_OK);for(unsigned i=0;i<3;i++){memset(copies[i],0,f->bytes[i]);free(copies[i]);}CHECK(!memcmp(&out,&saved,sizeof(out)));queries();
 printf("{\"passed\":true,\"checks\":%llu,\"fixtures\":%zu,\"cuts\":%llu,\"mutations\":%llu,\"cancellations\":%llu,\"authentic_poll_count\":%u,\"owner_bytes\":%zu,\"workspace_bytes\":%zu,\"sources_bytes\":%zu,\"control_bytes\":%zu,\"authentic_minimum_budget\":%zu,\"configured_old_reservation\":%zu,\"reader_heap_allocations\":0,\"runtime_generation\":false,\"actor_authority\":false}\n",checks,sizeof(fixtures)/sizeof(fixtures[0]),cuts,mutations,cancellations,polls,sizeof(out),sizeof(workspace),sizeof(sources),sizeof(control),minimum,old);return 0;}
